import{_ as e,H as t,f as a,i as _}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"围炉夜话 | 学了新技术，在公司用不上怎么办？","description":"","frontmatter":{},"headers":[],"relativePath":"Vue3企业级项目实战课/围炉夜话｜学了新技术，在公司用不上怎么办？.md","filePath":"Vue3企业级项目实战课/围炉夜话｜学了新技术，在公司用不上怎么办？.md","lastUpdated":1795535737000}'),A={name:"Vue3企业级项目实战课/围炉夜话｜学了新技术，在公司用不上怎么办？.md"};function p(s,E,i,r,B,n){return t(),a("div",null,[...E[0]||(E[0]=[_('<h1 id="围炉夜话-学了新技术-在公司用不上怎么办" tabindex="-1">围炉夜话 | 学了新技术，在公司用不上怎么办？ <a class="header-anchor" href="#围炉夜话-学了新技术-在公司用不上怎么办" aria-label="Permalink to &quot;围炉夜话 | 学了新技术，在公司用不上怎么办？&quot;">​</a></h1><p>你好，我是杨文坚。</p><p>课程学到这里，不知道你的收获如何，通过基础篇的扫盲、进阶篇的训练、实战篇的部分搭建，我们已经学完一半多的知识点了，值得给你自己鼓个掌。</p><p>本来应该更新正文，但是快到春节了，可能很多人已经无心学习，所以，这周我安排了一个特别的“围炉夜话”环节，跟你聊一聊职业发展。</p><p>之前我做了一期训练营，同学们希望我多分享一些有关职业规划的内容，当时分享后大家觉得很实用，所以我特地整理了一些热点答疑，分享给你，希望也对你有启发。比如作为前端人明年该关注哪些新技术、如果学了新技术公司用不上怎么办、前端职业前景怎么样、怎么规划自己的职业生涯等等；另外，还会聊一些职场话题，比如怎么看懂 Leader 在想什么。</p><p>要先说明一下，聊天内容都是出于我自己的视⻆和经历讲的一些话，如果你有其他的观点和想法，非常欢迎留言，我们一起讨论。</p><p>今天我们会聊到 3 个问题。</p><p>问题 1：想看看老师对前端程序员这个职业的前景判断，供大于求的状况是会一直持续下去吗？毕竟每年毕业的计算机专业的学生那么多，也有其他行业转岗过来的，感觉这个行业的从业者很多，但是现在岗位很少？</p><p>问题 2：前端的发展方向和细分领域是怎么样的？技术趋势怎么看？</p><p>问题 3：公司用的技术栈比较老，学了新的技术在公司也无用武之地，老师怎么看？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Vue3%E4%BC%81%E4%B8%9A%E7%BA%A7%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%259B%25B4%25E7%2582%2589%25E5%25A4%259C%25E8%25AF%259D-%25E5%25AD%25A6%25E4%25BA%2586%25E6%2596%25B0%25E6%258A%2580%25E6%259C%25AF%25EF%25BC%258C%25E5%259C%25A8%25E5%2585%25AC%25E5%258F%25B8%25E7%2594%25A8%25E4%25B8%258D%25E4%25B8%258A%25E6%2580%258E%25E4%25B9%2588%25E5%258A%259E%25EF%25BC%259F/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Vue3%E4%BC%81%E4%B8%9A%E7%BA%A7%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%259B%25B4%25E7%2582%2589%25E5%25A4%259C%25E8%25AF%259D-%25E5%25AD%25A6%25E4%25BA%2586%25E6%2596%25B0%25E6%258A%2580%25E6%259C%25AF%25EF%25BC%258C%25E5%259C%25A8%25E5%2585%25AC%25E5%258F%25B8%25E7%2594%25A8%25E4%25B8%258D%25E4%25B8%258A%25E6%2580%258E%25E4%25B9%2588%25E5%258A%259E%25EF%25BC%259F/1.jpeg" alt=""></a></p><p>期待看到你对这三个问题的看法，欢迎留言，参与讨论。</p>',12)])])}const l=e(A,[["render",p]]);export{c as __pageData,l as default};
